21	/// Drain any residual key events already queued in the terminal buffer.
22	///
23	/// On Windows, transitioning between raw mode and cooked mode (or between
24	/// successive raw-mode prompts) can leave stale events (e.g. the Release
25	/// half of an Enter keypress) in the queue. Consuming them with a
26	/// non-blocking poll prevents the next prompt from mis-firing.
27	fn drain_pending_events() {
28	    while event::poll(std::time::Duration::ZERO).unwrap_or(false) {
29	        let _ = event::read();
30	    }
31	}
