33	/// Display a numbered menu and get user selection.
34	///
35	/// Returns the index (0-based) of the selected option.
36	/// Pressing Enter without input selects the first option (index 0).
37	///
38	/// # Example
39	///
40	/// ```ignore
41	/// let choice = select_one("Choose an option:", &["Option A", "Option B"]);
42	/// ```
43	pub fn select_one(prompt: &str, options: &[&str]) -> io::Result<usize> {
44	    let mut stdout = io::stdout();
45	
46	    // Print prompt
47	    writeln!(stdout, "{}", prompt)?;
48	    writeln!(stdout)?;
49	
50	    // Print options
51	    for (i, option) in options.iter().enumerate() {
52	        writeln!(stdout, "  [{}] {}", i + 1, option)?;
53	    }
54	    writeln!(stdout)?;
55	
56	    loop {
57	        print!("> ");
58	        stdout.flush()?;
59	
60	        let mut input = String::new();
61	        io::stdin().read_line(&mut input)?;
62	        let input = input.trim();
63	
64	        // Handle empty input as first option
65	        if input.is_empty() {
66	            return Ok(0);
67	        }
68	
69	        // Parse number
70	        if let Ok(num) = input.parse::<usize>()
71	            && num >= 1
72	            && num <= options.len()
73	        {
74	            return Ok(num - 1);
75	        }
76	
77	        writeln!(
78	            stdout,
79	            "Invalid choice. Please enter a number 1-{}.",
80	            options.len()
81	        )?;
82	    }
83	}
