85	/// Multi-select with space to toggle, enter to confirm.
86	///
87	/// `options` is a slice of (label, initially_selected) tuples.
88	/// Returns indices of selected options.
89	///
90	/// # Example
91	///
92	/// ```ignore
93	/// let selected = select_many("Select channels:", &[
94	///     ("CLI/TUI", true),
95	///     ("HTTP webhook", false),
96	///     ("Telegram", false),
97	/// ])?;
98	/// ```
99	pub fn select_many(prompt: &str, options: &[(&str, bool)]) -> io::Result<Vec<usize>> {
100	    if options.is_empty() {
101	        return Ok(vec![]);
102	    }
103	
104	    let mut stdout = io::stdout();
105	    let mut selected: Vec<bool> = options.iter().map(|(_, s)| *s).collect();
106	    let mut cursor_pos = 0;
107	
108	    terminal::enable_raw_mode()?;
109	    drain_pending_events();
110	    execute!(stdout, cursor::Hide)?;
111	
112	    let result = (|| {
113	        loop {
114	            // Clear and redraw
115	            execute!(stdout, cursor::MoveToColumn(0))?;
116	
117	            writeln!(stdout, "{}\r", prompt)?;
118	            writeln!(stdout, "\r")?;
119	            writeln!(
120	                stdout,
121	                "  (Use arrow keys to navigate, space to toggle, enter to confirm)\r"
122	            )?;
123	            writeln!(stdout, "\r")?;
124	
125	            for (i, (label, _)) in options.iter().enumerate() {
126	                if i == cursor_pos {
127	                    // Cursor line: cyan cursor, then colored checkbox
128	                    execute!(stdout, SetForegroundColor(Color::Cyan))?;
129	                    write!(stdout, "  \u{25b8} ")?;
130	                    if selected[i] {
131	                        execute!(stdout, SetForegroundColor(Color::Green))?;
132	                        write!(stdout, "[\u{2713}]")?;
133	                    } else {
134	                        execute!(stdout, SetForegroundColor(Color::DarkGrey))?;
135	                        write!(stdout, "[\u{00b7}]")?;
136	                    }
137	                    execute!(stdout, SetForegroundColor(Color::Cyan))?;
138	                    writeln!(stdout, " {}\r", label)?;
139	                    execute!(stdout, ResetColor)?;
140	                } else {
141	                    write!(stdout, "    ")?;
142	                    if selected[i] {
143	                        execute!(stdout, SetForegroundColor(Color::Green))?;
144	                        write!(stdout, "[\u{2713}]")?;
145	                        execute!(stdout, ResetColor)?;
146	                    } else {
147	                        execute!(stdout, SetForegroundColor(Color::DarkGrey))?;
148	                        write!(stdout, "[\u{00b7}]")?;
149	                        execute!(stdout, ResetColor)?;
150	                    }
151	                    writeln!(stdout, " {}\r", label)?;
152	                }
153	            }
154	
155	            stdout.flush()?;
156	
157	            // Read key — only act on Press events to avoid double-firing
158	            // from Release/Repeat events on Windows.
159	            if let Event::Key(KeyEvent {
160	                code,
161	                modifiers,
162	                kind: KeyEventKind::Press,
163	                ..
164	            }) = event::read()?
165	            {
166	                match code {
167	                    KeyCode::Up => {
168	                        cursor_pos = cursor_pos.saturating_sub(1);
169	                    }
170	                    KeyCode::Down => {
171	                        if cursor_pos < options.len() - 1 {
172	                            cursor_pos += 1;
173	                        }
174	                    }
175	                    KeyCode::Char(' ') => {
176	                        selected[cursor_pos] = !selected[cursor_pos];
177	                    }
178	                    KeyCode::Enter => {
179	                        break;
180	                    }
181	                    KeyCode::Char('c') if modifiers.contains(KeyModifiers::CONTROL) => {
182	                        return Err(io::Error::new(io::ErrorKind::Interrupted, "Ctrl-C"));
183	                    }
184	                    _ => {}
185	                }
186	
187	                // Move cursor up to redraw
188	                execute!(
189	                    stdout,
190	                    cursor::MoveUp((options.len() + 4) as u16),
191	                    terminal::Clear(ClearType::FromCursorDown)
192	                )?;
193	            }
194	        }
195	        Ok(())
196	    })();
197	
198	    // Cleanup
199	    execute!(stdout, cursor::Show)?;
200	    terminal::disable_raw_mode()?;
201	    writeln!(stdout)?;
202	
203	    result?;
204	
205	    Ok(selected
206	        .iter()
207	        .enumerate()
208	        .filter_map(|(i, &s)| if s { Some(i) } else { None })
209	        .collect())
210	}
