212	/// Password/secret input with hidden characters.
213	///
214	/// # Example
215	///
216	/// ```ignore
217	/// let token = secret_input("Bot token")?;
218	/// ```
219	pub fn secret_input(prompt: &str) -> io::Result<SecretString> {
220	    let mut stdout = io::stdout();
221	
222	    print!("{}: ", prompt);
223	    stdout.flush()?;
224	
225	    terminal::enable_raw_mode()?;
226	    let result = read_secret_line();
227	    terminal::disable_raw_mode()?;
228	
229	    writeln!(stdout)?;
230	    result
231	}
