233	fn read_secret_line() -> io::Result<SecretString> {
234	    let mut input = String::new();
235	    let mut stdout = io::stdout();
236	
237	    drain_pending_events();
238	
239	    loop {
240	        // Only act on Press events to avoid double-firing from
241	        // Release/Repeat events on Windows.
242	        if let Event::Key(KeyEvent {
243	            code,
244	            modifiers,
245	            kind: KeyEventKind::Press,
246	            ..
247	        }) = event::read()?
248	        {
249	            match code {
250	                KeyCode::Enter => {
251	                    break;
252	                }
253	                KeyCode::Backspace => {
254	                    if !input.is_empty() {
255	                        input.pop();
256	                        execute!(stdout, Print("\x08 \x08"))?;
257	                        stdout.flush()?;
258	                    }
259	                }
260	                KeyCode::Char('c') if modifiers.contains(KeyModifiers::CONTROL) => {
261	                    return Err(io::Error::new(io::ErrorKind::Interrupted, "Ctrl-C"));
262	                }
263	                KeyCode::Char(c) => {
264	                    input.push(c);
265	                    execute!(stdout, Print('*'))?;
266	                    stdout.flush()?;
267	                }
268	                _ => {}
269	            }
270	        }
271	    }
272	
273	    Ok(SecretString::from(input))
274	}
