276	/// Yes/no confirmation prompt.
277	///
278	/// # Example
279	///
280	/// ```ignore
281	/// if confirm("Enable Telegram channel?", false)? {
282	///     // ...
283	/// }
284	/// ```
285	pub fn confirm(prompt: &str, default: bool) -> io::Result<bool> {
286	    let mut stdout = io::stdout();
287	
288	    let hint = if default { "[Y/n]" } else { "[y/N]" };
289	    print!("{} {} ", prompt, hint);
290	    stdout.flush()?;
291	
292	    let mut input = String::new();
293	    io::stdin().read_line(&mut input)?;
294	    let input = input.trim().to_lowercase();
295	
296	    Ok(match input.as_str() {
297	        "" => default,
298	        "y" | "yes" => true,
299	        "n" | "no" => false,
300	        _ => default,
301	    })
302	}
