330	/// Print a compact dot-based step indicator.
331	///
332	/// `●` = completed (green/success), `◉` = current (accent), `○` = remaining (dim).
333	///
334	/// # Example
335	///
336	/// ```ignore
337	/// print_step(3, 5, "Model Selection");
338	/// // Output:   ● ● ◉ ○ ○   Model Selection
339	/// ```
340	pub fn print_step(current: usize, total: usize, name: &str) {
341	    use crate::cli::fmt;
342	    let mut dots = String::new();
343	    for i in 1..=total {
344	        if i > 1 {
345	            dots.push(' ');
346	        }
347	        if i < current {
348	            dots.push_str(&format!("{}\u{25CF}{}", fmt::success(), fmt::reset())); // ● green
349	        } else if i == current {
350	            dots.push_str(&format!("{}\u{25C9}{}", fmt::accent(), fmt::reset())); // ◉ accent
351	        } else {
352	            dots.push_str(&format!("{}\u{25CB}{}", fmt::dim(), fmt::reset())); // ○ dim
353	        }
354	    }
355	    println!("  {}   {}", dots, name);
356	    println!();
357	}
