406	/// Read an optional line of input (empty returns None).
407	pub fn optional_input(prompt: &str, hint: Option<&str>) -> io::Result<Option<String>> {
408	    let mut stdout = io::stdout();
409	
410	    if let Some(h) = hint {
411	        print!("{} ({}): ", prompt, h);
412	    } else {
413	        print!("{}: ", prompt);
414	    }
415	    stdout.flush()?;
416	
417	    let mut input = String::new();
418	    io::stdin().read_line(&mut input)?;
419	    let input = input.trim();
420	
421	    if input.is_empty() {
422	        Ok(None)
423	    } else {
424	        Ok(Some(input.to_string()))
425	    }
426	}
