39	/// Check if onboarding is needed and return the reason.
40	///
41	/// Reads environment variables (`DATABASE_URL`, `LIBSQL_PATH`,
42	/// `ONBOARD_COMPLETED`, `NEARAI_API_KEY`) and checks for the default
43	/// session file on disk. Not safe to call concurrently with `env::set_var`.
44	#[cfg(any(feature = "postgres", feature = "libsql"))]
45	pub fn check_onboard_needed() -> Option<&'static str> {
46	    let has_db = std::env::var("DATABASE_URL").is_ok()
47	        || std::env::var("LIBSQL_PATH").is_ok()
48	        || crate::config::default_libsql_path().exists();
49	
50	    if !has_db {
51	        return Some("Database not configured");
52	    }
53	
54	    if std::env::var("ONBOARD_COMPLETED")
55	        .map(|v| v == "true")
56	        .unwrap_or(false)
57	    {
58	        return None;
59	    }
60	
61	    if std::env::var("NEARAI_API_KEY").is_err() {
62	        let session_path = crate::config::default_session_path();
63	        if !session_path.exists() {
64	            return Some("First run");
65	        }
66	    }
67	
68	    None
69	}
